import{_ as a,o as e,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Targeted Attacks and Anatomy","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/targeting-and-anatomy.md","filePath":"en/guide/combat/targeting-and-anatomy.md"}'),r={name:"en/guide/combat/targeting-and-anatomy.md"};function o(d,t,s,l,c,h){return e(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="targeted-attacks-and-anatomy" tabindex="-1">Targeted Attacks and Anatomy <a class="header-anchor" href="#targeted-attacks-and-anatomy" aria-label="Permalink to &quot;Targeted Attacks and Anatomy&quot;">​</a></h1><p><strong>Status:</strong> Accepted targeting direction · Experimental Anatomy integrated in a limited scope · Aimed attacks not implemented · Proposed broader interactions.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Anatomy can provide qualitative body-condition information on a successful assessment.</li><li>Choosing a region requests an attempt, never a guaranteed hit there.</li><li>Assessment does not reveal exact local integrity or hidden aiming probabilities.</li></ul><p><span id="information-helps-you-choose"></span><span id="a-choice-is-an-attempt"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Meaning</th></tr></thead><tbody><tr><td>Observe</td><td>Anatomy’s current experiment describes regional condition for eligible human players; it is not universal creature diagnosis.</td></tr><tr><td>Choose</td><td>Optional aiming expresses a preferred region while ordinary combat can continue.</td></tr><tr><td>Resolve</td><td>The server decides whether the action hits and where it actually lands. Selection grants no extra swing or recovery reset.</td></tr><tr><td>Interpret</td><td>Broader roles for Tactics, Arms Lore, Healing and hunting knowledge remain future possibilities.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands</th></tr></thead><tbody><tr><td>Anatomy supports combat damage and Healing</td><td>Add permitted qualitative local-condition information to informed decisions.</td></tr><tr><td>Selecting an opponent starts an attack relationship</td><td>A separate optional region preference would express intent without guaranteeing impact.</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An assessment reports an injured arm. You may want to exploit that weakness, but future aimed attacks would still have to hit and resolve their actual impact location.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/limbs-and-trauma.html">Limbs and Trauma</a> · <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">Skills and knowledge</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/targeting.html">Read the full design specification</a></p>',15)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
